-- Sprint 10: opening is the internal useful size, stored in integer millimetres.
create table public.framing_settings (business_id uuid primary key references public.businesses(id) on delete restrict,default_markup_percent integer not null default 0 check(default_markup_percent>=0),default_labour_cents bigint not null default 0 check(default_labour_cents>=0),default_moulding_waste_percent integer not null default 0 check(default_moulding_waste_percent>=0),default_material_waste_percent integer not null default 0 check(default_material_waste_percent>=0),updated_at timestamptz not null default now());
create table public.frame_mouldings (id uuid primary key,business_id uuid not null references public.businesses(id) on delete restrict,code text,name text not null check(length(btrim(name))>0),description text,face_width_mm integer check(face_width_mm is null or face_width_mm>0),cost_per_meter_cents bigint not null check(cost_per_meter_cents>=0),sale_price_per_meter_cents bigint check(sale_price_per_meter_cents is null or sale_price_per_meter_cents>=0),waste_percent integer check(waste_percent is null or waste_percent>=0),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,id));
create table public.frame_materials (id uuid primary key,business_id uuid not null references public.businesses(id) on delete restrict,name text not null check(length(btrim(name))>0),material_type text not null check(material_type in('glass','backing','passepartout','print','other')),pricing_unit text not null check(pricing_unit in('square_meter','linear_meter','unit')),cost_cents bigint not null check(cost_cents>=0),sale_price_cents bigint check(sale_price_cents is null or sale_price_cents>=0),waste_percent integer check(waste_percent is null or waste_percent>=0),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,id));
create table public.frame_quotes (id uuid primary key,business_id uuid not null references public.businesses(id) on delete restrict,branch_id uuid not null,customer_id uuid,width_mm integer not null check(width_mm>0),height_mm integer not null check(height_mm>0),measurement_mode text not null check(measurement_mode='opening'),status text not null check(status in('draft','quoted','accepted','rejected','expired')),notes text,subtotal_cents bigint not null check(subtotal_cents>=0),total_cents bigint not null check(total_cents>=0),created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,id),foreign key(business_id,branch_id) references public.branches(business_id,id),foreign key(business_id,customer_id) references public.customers(business_id,id));
create table public.frame_quote_items (id uuid primary key,business_id uuid not null references public.businesses(id) on delete restrict,quote_id uuid not null,name_snapshot text not null,item_type text not null check(item_type in('moulding','material','labour')),source_id uuid,quantity_numerator bigint not null check(quantity_numerator>0),quantity_denominator bigint not null check(quantity_denominator>0),unit text not null check(unit in('square_meter','linear_meter','unit','labour')),unit_price_cents bigint not null check(unit_price_cents>=0),total_cents bigint not null check(total_cents>=0),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,id),foreign key(business_id,quote_id) references public.frame_quotes(business_id,id));
create table public.frame_jobs (id uuid primary key,business_id uuid not null references public.businesses(id) on delete restrict,branch_id uuid not null,quote_id uuid not null,customer_id uuid,status text not null check(status in('pending','in_progress','ready','delivered','cancelled')),promised_at timestamptz,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,id),unique(business_id,quote_id),foreign key(business_id,branch_id) references public.branches(business_id,id),foreign key(business_id,quote_id) references public.frame_quotes(business_id,id),foreign key(business_id,customer_id) references public.customers(business_id,id));
alter table public.framing_settings enable row level security; alter table public.frame_mouldings enable row level security; alter table public.frame_materials enable row level security; alter table public.frame_quotes enable row level security; alter table public.frame_quote_items enable row level security; alter table public.frame_jobs enable row level security;
create policy framing_settings_read on public.framing_settings for select to authenticated using(private.has_active_membership(business_id)); create policy framing_settings_write on public.framing_settings for all to authenticated using(private.has_active_membership(business_id)) with check(private.has_active_membership(business_id));
create policy frame_mouldings_access on public.frame_mouldings for all to authenticated using(private.has_active_membership(business_id)) with check(private.has_active_membership(business_id)); create policy frame_materials_access on public.frame_materials for all to authenticated using(private.has_active_membership(business_id)) with check(private.has_active_membership(business_id)); create policy frame_quotes_access on public.frame_quotes for all to authenticated using(private.has_active_membership(business_id)) with check(private.has_active_membership(business_id)); create policy frame_quote_items_access on public.frame_quote_items for all to authenticated using(private.has_active_membership(business_id)) with check(private.has_active_membership(business_id)); create policy frame_jobs_access on public.frame_jobs for all to authenticated using(private.has_active_membership(business_id)) with check(private.has_active_membership(business_id));
grant select,insert,update on public.framing_settings,public.frame_mouldings,public.frame_materials,public.frame_quotes,public.frame_quote_items,public.frame_jobs to authenticated;
